def phrase_present(text: str, phrase: str) -> bool:
    """Unicode-aware boundaries block Java in JavaScript and Go in ongoing."""
    return bool(re.search(r"(?<![\w])" + re.escape(phrase) + r"(?![\w])", text, flags=re.I))


def canonicalize_names(names):
    """Return canonical labels for known aliases, retaining unrecognized names."""
    return sorted({REVIEWED_ALIASES.get(name.casefold(), name) for name in names}, key=str.casefold)
